export const GUIDE_BODY =
  '<header class="nav"><a class="brand" href="/"><img class="brand-logo" src="/brand/logo-mark-ink.png" alt="Paratha Land" width="560" height="139"></a>\n<nav aria-label="Main"><ul><li><a href="/#order">Menu</a></li><li><a href="/catering">Catering & truck</a></li><li><a href="/#rewards">Rewards</a></li><li><a href="/#visit">Visit</a></li></ul></nav>\n<a class="btn btn-gold nav-cta" href="/#order">Order pickup</a>\n<button class="burger" type="button" data-menu-open aria-label="Open menu"><svg viewBox="0 0 24 24" fill="none"><path d="M3 7h18M3 12h18M3 17h18" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg></button></header>\n<div class="mnav" role="dialog" aria-label="Menu"><button class="burger x" type="button" data-menu-close aria-label="Close menu" style="display:block"><svg viewBox="0 0 24 24" fill="none"><path d="M6 6l12 12M18 6 6 18" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg></button>\n<img src="/brand/belan.png" alt="" width="600" height="87" style="width:180px;height:auto;margin-bottom:18px"><a href="/">Home</a><a href="/#order">Menu</a><a href="/catering">Catering & truck</a><a href="/#rewards">Rewards</a><a href="/#visit">Visit</a><a href="tel:+16043409237">Call (604) 340-9237</a></div>\n<main>\n<section class="g-hero" aria-labelledby="g-h">\n  <div class="wrap">\n    <nav class="crumbs" aria-label="Breadcrumb"><a href="/">Home</a> / Best parathas in Langley</nav>\n    <h1 id="g-h">The best parathas in Langley: <span class="hi">a local guide to Punjabi parathas</span></h1>\n    <p class="lead">What makes a great paratha, which one to order, what else to eat with it, and where to get one hot off the tawa in Langley, BC.</p>\n    <p class="g-meta">By Paratha Land · Updated <time datetime="2026-11-25">25 November 2026</time></p>\n  </div>\n</section>\n<div class="band"></div>\n<article class="light article">\n  <div class="answer">\n    <h2>The short answer</h2>\n    <p>For hand-stuffed Punjabi parathas in Langley, go to <b>Paratha Land</b> at 20381 62 Ave, Unit 301, Langley, BC. Every paratha is stuffed and rolled to order: aloo, gobi, paneer, paneer bhurji, mooli, methi and makki methi. There\'s also saag with makki roti, chhole poori, rice bowls, Punjabi sweets and chai, and the whole menu is vegetarian. Order for pickup at <a class="inline" href="/#order">parathaland.com</a> or call <a class="inline" href="tel:+16043409237">(604) 340-9237</a>.</p>\n  </div>\n  \n<nav class="toc" aria-label="On this page"><b>On this page</b><ol>\n<li><a href="#great">What makes a great paratha</a></li><li><a href="#which">Which paratha to order</a></li><li><a href="#more">More Punjabi food to try</a></li>\n<li><a href="#eat">How to eat a paratha</a></li><li><a href="#vs">Paratha vs roti vs naan</a></li><li><a href="#order">Ordering, catering and the food truck</a></li><li><a href="#faq">Questions</a></li></ol></nav>\n\n<h2 id="great">What makes a great paratha</h2>\n<p>Every Punjabi family has an opinion on parathas, but the good ones share five things.</p>\n<ol class="steps">\n<li><b>Fresh, rested dough.</b> Whole wheat atta kneaded soft and left to rest, so it rolls thin without tearing.</li>\n<li><b>Filling right to the edges.</b> Potato mashed smooth and spiced well, so every bite has aloo in it, not just the middle.</li>\n<li><b>Rolled thin and even.</b> The belan does the work slowly, so the filling never breaks through.</li>\n<li><b>A hot iron tawa and real ghee.</b> Flipped as it blisters, brushed with ghee, until both sides are golden with crisp brown spots.</li>\n<li><b>Eaten hot.</b> A paratha is at its best within minutes of leaving the tawa, which is why ours are stuffed and rolled to order.</li>\n</ol>\n\n<h2 id="which">Which paratha should you order?</h2>\n<p>New to parathas? Start with aloo. Then work your way through the rest. Prices are for a single paratha at Paratha Land; plates start at $14.49, and the signature Aloo Paratha Plate is $17.49.</p>\n<div class="tablewrap"><table><thead><tr><th scope="col">Paratha</th><th scope="col">What\'s inside</th><th scope="col" class="num">Price</th></tr></thead><tbody><tr><th scope="row">Aloo Paratha</th><td>Spiced mashed potato with green chilli, coriander and onion. The classic, and the one to try first.</td><td class="num">$6.49</td></tr><tr><th scope="row">Gobi Paratha</th><td>Finely grated cauliflower with ginger and spices. Lighter, with a little crunch.</td><td class="num">$6.99</td></tr><tr><th scope="row">Paneer Paratha</th><td>Crumbled paneer with herbs and spices. Rich, soft and filling.</td><td class="num">$8.99</td></tr><tr><th scope="row">Mooli Paratha</th><td>Grated white radish, squeezed dry and spiced. Peppery and fresh.</td><td class="num">$7.49</td></tr><tr><th scope="row">Methi Paratha</th><td>Fresh fenugreek leaves worked into the dough. Slightly bitter in a good way.</td><td class="num">$5.99</td></tr><tr><th scope="row">Mix Veg Paratha</th><td>Chopped mixed vegetables with spices.</td><td class="num">$5.99</td></tr><tr><th scope="row">Makki Methi Paratha</th><td>Maize (corn) flour with fenugreek. A Punjabi winter favourite.</td><td class="num">$7.99</td></tr><tr><th scope="row">Makki Methi Mooli Paratha</th><td>Maize flour with fenugreek and radish.</td><td class="num">$7.99</td></tr><tr><th scope="row">Namak Ajwain Parantha</th><td>No filling: layered with salt and carom seeds. Perfect with chai.</td><td class="num">$4.99</td></tr><tr><th scope="row">Chinni Paratha</th><td>A sweet paratha made with sugar, loved by kids.</td><td class="num">$4.99</td></tr><tr><th scope="row">Plain Paratha</th><td>Flaky and layered, to go with any curry.</td><td class="num">$3.99</td></tr></tbody></table></div>\n\n<h2 id="more">More Punjabi food worth trying in Langley</h2>\n<p>Parathas are the star, but a proper Punjabi meal has more on the table.</p>\n<ul class="ticks">\n<li><b>Saag and makki roti</b> ($16.99): slow-cooked greens with maize-flour roti, the dish Punjab is famous for in winter.</li>\n<li><b>Chhole poori</b> ($15.99) and <b>halwa poori</b> ($15.99): spiced chickpeas with puffed pooris, the classic weekend breakfast.</li>\n<li><b>Rajma chawal</b> ($16.99), <b>kadhi chawal</b> ($16.99) and <b>dal khichdi</b> ($16.99): the comfort food every Punjabi grew up on.</li>\n<li><b>Sweets:</b> gajar halwa ($9.99), moong dal halwa ($8.50), rasmalai ($6.99) and seviyan ($9.99).</li>\n<li><b>Chai and lassi:</b> masala, elaichi, ginger and gurwali chai, dudh patti ($6.50), and sweet or salted lassi ($8.50).</li>\n</ul>\n<p><a class="inline" href="/#order">See the full menu with prices</a></p>\n\n<h2 id="eat">How to eat a paratha the Punjabi way</h2>\n<p>Put a slab of white butter on top and let it melt. Tear a piece with your right hand, scoop up some dahi to cool it down, and take a small bite of achar for heat. Keep a cup of chai close. Repeat until the plate is empty.</p>\n\n<h2 id="vs">Paratha vs roti vs naan</h2>\n<ul class="ticks">\n<li><b>Roti</b> is plain whole wheat flatbread, thin and cooked dry on a tawa. It goes with curries every day.</li>\n<li><b>Paratha</b> is richer: layered or stuffed, and cooked with ghee or butter until crisp in spots. It can be a meal on its own.</li>\n<li><b>Naan</b> is made from leavened white flour and baked in a tandoor. It\'s a restaurant bread more than a home one.</li>\n</ul>\n\n<h2 id="order">Ordering, catering and the food truck</h2>\n<p>Paratha Land is at <b>20381 62 Ave, Unit 301, Langley, BC V3A 5E6</b>. Order online for pickup, call <a class="inline" href="tel:+16043409237">(604) 340-9237</a>, or check reviews on <a class="inline" href="https://share.google/xiSuF9gGfN1qYML7r" target="_blank" rel="noopener">Google</a>.</p>\n<p><b>Hours:</b> Tuesday to Friday and Sunday 7 a.m.–2 p.m. and 5 p.m.–4:30 a.m., Saturday 7 a.m.–4:30 a.m. straight through, closed Monday. It\'s one of the few places in Langley serving fresh parathas late at night, until 4:30 a.m.</p>\n<p>Feeding a crowd? We cater birthdays, office lunches and family functions, and our food truck can cook parathas fresh on-site at your concert, mela or corporate event. <a class="inline" href="/catering">Request a catering quote or book the truck</a>.</p>\n<div class="cta-row"><a class="btn btn-ink" href="/#order">Order for pickup <svg viewBox="0 0 18 18" fill="none" aria-hidden="true"><path d="M3 9h12m-5-5 5 5-5 5" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg></a><a class="btn btn-line" style="color:var(--ink);box-shadow:inset 0 0 0 2px var(--line-l)" href="/catering">Catering &amp; food truck</a></div>\n<p class="note" style="margin-top:22px">Follow Paratha Land on <a href="https://www.instagram.com/paratha_land/" target="_blank" rel="noopener me">Instagram</a> · <a href="https://www.facebook.com/parathaland/" target="_blank" rel="noopener me">Facebook</a> · <a href="https://www.youtube.com/channel/UCSX_j5AfRV9HXJ3RLaq4X7A" target="_blank" rel="noopener me">YouTube</a>.</p>\n\n</article>\n<section class="light g-faq" id="faq" aria-labelledby="gfaq-h">\n  <h2 class="h2" id="gfaq-h" style="font-size:clamp(34px,4vw,52px)">Questions about parathas in Langley</h2>\n  <div class="faq"><details><summary>Where can I get the best aloo paratha in Langley, BC?</summary><p>Paratha Land at 20381 62 Ave, Unit 301, Langley makes hand-stuffed aloo parathas to order, cooked on a hot tawa and served with butter. The Aloo Paratha Plate is the signature dish. Order online for pickup at parathaland.com or call (604) 340-9237.</p></details><details><summary>Where can I find Punjabi food in Langley?</summary><p>Paratha Land serves Punjabi home-style food in Langley: stuffed parathas, saag with makki roti, chhole poori, rajma chawal, kadhi chawal, dal khichdi, Punjabi sweets like gajar halwa and rasmalai, plus chai and lassi.</p></details><details><summary>Where can I get late-night Indian food in Langley?</summary><p>Paratha Land in Langley is open until 4:30 a.m. every night except Monday, serving hot parathas, curries, rice bowls and chai. Hours: Tuesday to Friday and Sunday 7 a.m.–2 p.m. and 5 p.m.–4:30 a.m., Saturday 7 a.m.–4:30 a.m. straight through, closed Monday.</p></details><details><summary>Is Paratha Land vegetarian?</summary><p>Yes. Every item on the Paratha Land menu is vegetarian.</p></details><details><summary>What is the difference between a paratha and a roti?</summary><p>A roti is a plain, thin whole wheat flatbread cooked dry on a tawa. A paratha is richer: it is layered or stuffed (with potato, cauliflower, paneer or radish) and cooked with ghee or butter until golden and crisp in spots.</p></details><details><summary>What do you eat with a paratha?</summary><p>Traditionally a paratha comes with a slab of white butter on top, dahi (yogurt) to cool it down and achar (pickle) for heat, with a cup of chai on the side.</p></details><details><summary>Does Paratha Land do catering or a food truck in Langley?</summary><p>Yes. Paratha Land caters birthdays, office lunches and family functions, and brings its food truck to concerts, festivals, melas and corporate events. Request a quote at parathaland.com/catering.</p></details></div>\n</section>\n</main>\n<footer class="foot"><div class="foot-grid">\n<div><a class="brand" href="/"><img class="foot-logo" src="/brand/logo-mark-cream.png" alt="Paratha Land" width="560" height="139" loading="lazy"></a><p style="margin:18px 0 0;max-width:300px">Hand-stuffed Punjabi parathas, always made fresh in Langley, BC. Fully vegetarian. <span lang="pa" class="pa" style="color:var(--gold)">ਘਰ ਵਰਗਾ ਸੁਆਦ</span></p></div>\n<div><h2 class="fh">Order</h2><ul><li><a href="/#order">Pickup menu</a></li><li><a href="/#rewards">Paratha Club rewards</a></li><li><a href="/catering">Catering</a></li><li><a href="/catering#truck">Book the food truck</a></li></ul></div>\n<div><h2 class="fh">Find us</h2><address>20381 62 Ave, Unit 301<br>Langley, BC V3A 5E6<br><a href="tel:+16043409237">(604) 340-9237</a></address></div>\n<div><h2 class="fh">Follow &amp; find us</h2><div class="socials"><a href="https://www.instagram.com/paratha_land/" target="_blank" rel="noopener me" aria-label="Paratha Land on Instagram"><svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><rect x="3" y="3" width="18" height="18" rx="5" stroke="currentColor" stroke-width="2"/><circle cx="12" cy="12" r="4" stroke="currentColor" stroke-width="2"/><circle cx="17.5" cy="6.5" r="1.2" fill="currentColor"/></svg></a><a href="https://www.facebook.com/parathaland/" target="_blank" rel="noopener me" aria-label="Paratha Land on Facebook"><svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M14 8h3V4h-3a4 4 0 0 0-4 4v3H7v4h3v6h4v-6h3l1-4h-4V8z" fill="currentColor"/></svg></a><a href="https://www.youtube.com/channel/UCSX_j5AfRV9HXJ3RLaq4X7A" target="_blank" rel="noopener me" aria-label="Paratha Land on YouTube"><svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><rect x="2" y="5" width="20" height="14" rx="4" stroke="currentColor" stroke-width="2"/><path d="M10 9v6l5-3z" fill="currentColor"/></svg></a></div><ul><li><a href="https://share.google/xiSuF9gGfN1qYML7r" target="_blank" rel="noopener">Reviews on Google</a></li><li><a href="https://www.google.com/maps/search/?api=1&query=Paratha+Land+20381+62+Ave+Unit+301+Langley+BC" target="_blank" rel="noopener">Directions</a></li><li><a href="/best-paratha-langley">Best parathas in Langley</a></li><li><a href="/#faq">Questions</a></li></ul></div>\n</div><div class="foot-base"><span>© <span id="yr">2026</span> Paratha Land, Langley BC</span><span>Paratha · Aloo paratha · Indian street food · Punjabi food in Langley</span></div></footer>';
